d2; color: #ffffff; font-size: 16px; font-weight: 600; cursor: pointer; } .login-button:hover { background: #0f4fa8; } .login-message { display: none; margin-top: 20px; padding: 14px; border-radius: 8px; line-height: 1.5; font-size: 14px; } .login-message.error { display: block; background: #fee2e2; color: #991b1b; } .login-message.info { display: block; background: #dbeafe; color: #1e40af; } .login-links { text-align: center; margin-top: 25px; color: #64748b; line-height: 1.8; font-size: 14px; } @media (max-width: 500px) { .login-section { padding: 35px 15px; } .login-card { padding: 25px 20px; } .login-heading h1 { font-size: 26px; } } </style>
