               <header class="navbar"> <div class="container nav-container"> <a href="index.php" class="logo">TechConnect</a> <nav> <a href="index.php">Home</a> <a href="technicians.php">Find Technicians</a> <a href="register.php">Register</a> </nav> </div> </header> <!-- Login Section --> <main class="login-section"> <div class="login-card"> <div class="login-heading"> <div class="login-icon" aria-hidden="true"> &#128274; </div> <h1>Welcome Back!</h1> <p> Sign in to your TechConnect account to continue. </p> </div> <form class="login-form" id="loginForm"> <div class="form-group"> <label for="email">Email Address</label> <input type="email" id="email" name="email" placeholder="Enter your email address" autocomplete="email" required > </div> <div class="form-group"> <label for="password">Password</label> <div class="password-wrapper"> <input type="password" id="password" name="password" placeholder="Enter your password" autocomplete="current-password" required > <button type="button" class="toggle-password" id="togglePassword" aria-label="Show password" aria-pressed="false" > Show </button> </div> </div> <div class="login-options"> <label class="remember-me"> <input type="checkbox" id="remember" name="remember" > Remember me </label> <a href="#" id="forgotPassword"> Forgot password? </a> </div> <button type="submit" class="login-button"> Login to Account </button> <div id="loginMessage" class="login-message" role="status" aria-live="polite" ></div> </form> <div class="login-links"> Don't have an account? <a href="register.php">Create an account</a> <br> <a href="index.php">← Back to Home</a> </div> </div> </main> <!-- Footer --> <footer class="footer"> <div class="container"> <p> &copy; <?php echo date("Y"); ?> TechConnect. All rights reserved. </p> </div> </footer> <script> const loginForm = document.getElementById("loginForm"); const passwordInput = document.getElementById("password"); const togglePassword = document.getElementById("togglePassword"); const loginMessage = document.getElementById("loginMessage"); // Show or hide the password togglePassword.addEventListener("click", function() { const isHidden = passwordInput.type === "password"; passwordInput.type = isHidden ? "text" : "password"; togglePassword.textContent = isHidden ? "Hide" : "Show"; togglePassword.setAttribute( "aria-label", isHidden ? "Hide password" : "Show password" ); togglePassword.setAttribute( "aria-pressed", String(isHidden) ); }); // Demo login form loginForm.addEventListener("submit", function(event) { event.preventDefault(); loginMessage.className = "login-message info"; loginMessage.textContent = "The login form is working, but account authentication " + "will be available after the backend is connected."; }); // Demo forgot-password link document.getElementById("forgotPassword") .addEventListener("click", function(event) { event.preventDefault(); loginMessage.className = "login-message info"; loginMessage.textContent = "Password recovery will be available after the backend is connected."; }); </script> </body> </html>